with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published)
select id,'التنبؤات الاحتمالية والتحقق المتقدم من النماذج','عدم اليقين والتنبؤ التجميعي والمعايرة الإحصائية والتحقق المكاني والقيمة التشغيلية وجودة التنبؤ.',52,false from c
on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التنبؤ التجميعي والاحتمالي',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التحقق المتقدم والقيمة التشغيلية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('forecast-uncertainty-sources','مصادر عدم اليقين في التنبؤات الجوية','الرصد والتهيئة والفيزياء والحدود والنمذجة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ عدم اليقين من أخطاء الحالة الابتدائية والتمثيل العددي والفيزياء والشروط الحدية والتقلب الطبيعي. تختلف مساهمة كل مصدر باختلاف المتغير والمقياس الزمني، لذلك ينبغي فصل عدم اليقين عن الخطأ المعروف والانحياز القابل للتصحيح."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق مصادر عدم اليقين في التنبؤات الجوية سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم مصادر عدم اليقين في التنبؤات الجوية، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صنف مصادر عدم اليقين في توقع مطري لمدة ثلاثة أيام، وحدد ما يمكن تقليله وما لا يمكن إزالته."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد مصادر عدم اليقين في التنبؤات الجوية على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6560,55,'["شرح أسس مصادر عدم اليقين في التنبؤات الجوية","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('ensemble-forecasting-principles','مبادئ التنبؤ التجميعي','مجموعة حلول بديلة بدلاً من مسار واحد','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينتج التنبؤ التجميعي عدة محاكاة تختلف في الشروط الابتدائية أو إعدادات النموذج لتقدير نطاق السيناريوهات المحتملة. لا تعني كثرة الأعضاء ضمان جودة التوزيع؛ إذ تعتمد الفائدة على تنوع المجموعة ومعايرتها."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق مبادئ التنبؤ التجميعي سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم مبادئ التنبؤ التجميعي، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر كيف تختلف دلالة متوسط المجموعة عن انتشار أعضائها."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد مبادئ التنبؤ التجميعي على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6570,55,'["شرح أسس مبادئ التنبؤ التجميعي","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('ensemble-initial-condition-perturbations','اضطراب الشروط الابتدائية للأعضاء','تمثيل أخطاء التحليل الجوي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تولد اضطرابات مضبوطة حول الحالة الابتدائية لتمثيل عدم اليقين في التحليل. يجب أن تعكس الاضطرابات بنية الأخطاء الفيزيائية والمكانية، لا أن تكون ضوضاء عشوائية غير مقيدة."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق اضطراب الشروط الابتدائية للأعضاء سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم اضطراب الشروط الابتدائية للأعضاء، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح اختباراً يوضح ما إذا كانت اضطرابات البداية تمثل تبايناً واقعياً في التحليل."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد اضطراب الشروط الابتدائية للأعضاء على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6580,55,'["شرح أسس اضطراب الشروط الابتدائية للأعضاء","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('ensemble-model-uncertainty','تمثيل عدم يقين النموذج في المجموعات','تنوع الفيزياء والإعدادات والنماذج','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تستخدم المجموعات نماذج متعددة أو إعدادات فيزيائية مختلفة لتمثيل عدم يقين الصياغة. يتطلب تفسير التشتت الانتباه إلى اعتماد الأعضاء على بعضها وإلى الفروق المنهجية بين النماذج."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق تمثيل عدم يقين النموذج في المجموعات سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم تمثيل عدم يقين النموذج في المجموعات، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مجموعة تعتمد نموذجاً واحداً بإعدادات متعددة ومجموعة متعددة النماذج."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد تمثيل عدم يقين النموذج في المجموعات على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6590,55,'["شرح أسس تمثيل عدم يقين النموذج في المجموعات","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('ensemble-spread-skill','العلاقة بين انتشار المجموعة والمهارة','معايرة التشتت مقابل الخطأ الفعلي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس الانتشار تباعد أعضاء المجموعة، بينما تقيس المهارة قرب التنبؤ من الرصد. المجموعة الجيدة ينبغي أن يعكس انتشارها مستوى الخطأ المتوقع، ويمكن فحص العلاقة عبر عينات طويلة ومتجانسة."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق العلاقة بين انتشار المجموعة والمهارة سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم العلاقة بين انتشار المجموعة والمهارة، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر حالة يكون فيها انتشار المجموعة منخفضاً لكن الخطأ كبيراً."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد العلاقة بين انتشار المجموعة والمهارة على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6600,55,'["شرح أسس العلاقة بين انتشار المجموعة والمهارة","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('probabilistic-forecast-calibration','معايرة التنبؤات الاحتمالية','مطابقة الاحتمالات بالتواتر المرصود','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تكون التوقعات الاحتمالية معايرة عندما تتوافق الاحتمالات المتوقعة مع التواتر الفعلي على عينات مناسبة. يمكن فحص ذلك بمخططات الاعتمادية ومقاييس مثل Brier Score، مع مراعاة حجم العينة."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق معايرة التنبؤات الاحتمالية سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم معايرة التنبؤات الاحتمالية، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح معنى معايرة توقعات 30% عبر عدد كبير من الحالات."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد معايرة التنبؤات الاحتمالية على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6610,55,'["شرح أسس معايرة التنبؤات الاحتمالية","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('brier-score-probabilistic-verification','درجة براير للتحقق الاحتمالي','قياس جودة احتمالات الأحداث الثنائية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تقيس درجة براير متوسط مربع الفرق بين الاحتمال المتوقع والنتيجة الثنائية المرصودة، وتجمع بين جوانب المعايرة والتمييز في صورة واحدة. ينبغي مقارنتها بمرجع مناسب وتفسيرها بحسب معدل الحدث."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق درجة براير للتحقق الاحتمالي سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم درجة براير للتحقق الاحتمالي، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"احسب درجة براير لسلسلة صغيرة من الاحتمالات والنتائج، ثم فسر اتجاه التحسن."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"ال