ext","text":"يساعد الاعتمادية والتمييز وعدم اليقين على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6630,55,'["شرح أسس الاعتمادية والتمييز وعدم اليقين","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('roc-curve-weather-forecasting','منحنى ROC في التنبؤات الجوية','الموازنة بين الكشف والإنذارات الكاذبة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقارن منحنى ROC معدل الكشف الإيجابي بمعدل الإنذار الكاذب عند عتبات احتمالية مختلفة. يفيد في قياس التمييز لكنه لا يكفي وحده لتقييم معايرة الاحتمالات أو جودة القرار الاقتصادي."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق منحنى ROC في التنبؤات الجوية سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم منحنى ROC في التنبؤات الجوية، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يتغير POD وFPR عند تعديل عتبة الاحتمال."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد منحنى ROC في التنبؤات الجوية على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6640,55,'["شرح أسس منحنى ROC في التنبؤات الجوية","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('forecast-value-cost-loss','القيمة الاقتصادية للتنبؤات الجوية','نسبة الكلفة إلى الخسارة وقرار الإجراء','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتحدد قيمة التنبؤ وفق قرار المستخدم وكلفة الإجراء والخسارة المحتملة عند عدم الاستعداد. قد يكون التوقع نفسه ذا قيمة عالية لقطاع وحالة أقل قيمة لقطاع آخر بسبب اختلاف بنية القرار."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق القيمة الاقتصادية للتنبؤات الجوية سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم القيمة الاقتصادية للتنبؤات الجوية، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن قرارين لجهتين تختلفان في كلفة الوقاية والخسارة المحتملة من الحدث."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد القيمة الاقتصادية للتنبؤات الجوية على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6650,55,'["شرح أسس القيمة الاقتصادية للتنبؤات الجوية","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التنبؤ التجميعي والاحتمالي'),
('extreme-event-return-periods','فترات العودة للأحداث المتطرفة','الاحتمال السنوي وعدم ثبات المناخ','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تعبر فترة العودة عن مقلوب احتمال التجاوز السنوي في افتراضات معينة، ولا تعني أن الحدث يتكرر بانتظام كل تلك السنوات. يؤدي تغير المناخ وعدم ثبات التوزيع إلى تعقيد التقدير التاريخي."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق فترات العودة للأحداث المتطرفة سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم فترات العودة للأحداث المتطرفة، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"وضح الفرق بين حدث فترة عودته 100 سنة واحتمال حدوثه خلال سنة واحدة."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد فترات العودة للأحداث المتطرفة على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6660,55,'["شرح أسس فترات العودة للأحداث المتطرفة","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('extreme-value-distributions','توزيعات القيم المتطرفة','GEV وGPD وتحليل الذيل الإحصائي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم توزيعات القيم المتطرفة لوصف القيم القصوى أو التجاوزات فوق عتبة. يتطلب التقدير اختيار نموذج وعتبة وفحص الاستقلالية وملاءمة الذيل وعدم يقين المعلمات."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق توزيعات القيم المتطرفة سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم توزيعات القيم المتطرفة، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن منهج الكتل القصوى بمنهج التجاوز فوق العتبة من حيث البيانات والافتراضات."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد توزيعات القيم المتطرفة على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6670,55,'["شرح أسس توزيعات القيم المتطرفة","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('forecast-postprocessing-bias-correction','تصحيح انحياز التنبؤات','المعايرة الإحصائية مع الحفاظ على البنية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يهدف التصحيح إلى تقليل الانحياز المنهجي بين التنبؤ والرصد باستخدام علاقات إحصائية ملائمة. يجب تجنب تسرب بيانات التحقق إلى التدريب وفحص ثبات العلاقة عند تغير المناخ أو النموذج."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق تصحيح انحياز التنبؤات سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم تصحيح انحياز التنبؤات، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم تقسيم تدريب واختبار زمني لتصحيح انحياز الحرارة دون تسرب معلومات المستقبل."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد تصحيح انحياز التنبؤات على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6680,55,'["شرح أسس تصحيح انحياز التنبؤات","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('model-output-statistics','إحصاءات مخرجات النماذج MOS','ربط مخرجات النموذج بالرصد التاريخي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم MOS علاقات إحصائية تربط مخرجات النموذج بالتنبؤ المرصود، وقد تشمل الانحدار أو نماذج احتمالية. تعتمد صلاحيتها على تمثيل العينة واستقرار النموذج وتجانس سجلات المحطات."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق إحصاءات مخرجات النماذج MOS سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم إحصاءات مخرجات النماذج MOS، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد المتغيرات المتنبئة والاستجابة اللازمة لبناء MOS لدرجة الحرارة الدنيا."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد إحصاءات مخرجات النماذج MOS على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6690,55,'["شرح أسس إحصاءات مخرجات النماذج MOS","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('ensemble-model-output-statistics','الإحصاءات التجميعية EMOS','توزيع احتمالي من أعضاء المجموعة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تبني EMOS توزيعاً احتماليّاً معايراً انطلاقاً من إحصاءات أعضاء المجموعة، مثل المتوسط والانتشار. تساعد في تصحيح الانحياز ونقص الانتشار، مع ضرورة اختبار افتراض التوزيع ومعايرته موسمياً ومكانياً."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق الإحصاءات التجميعية EMOS سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم الإحصاءات التجميعية EMOS، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يمكن لـ EMOS معالجة مجموعة ضيقة الانتشار ومنحازة."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد الإحصاءات التجميعية EMOS على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6700,55,'["شرح أسس الإحصاءات التجميعية EMOS","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('spatial-verification-fss','مقياس المهارة في الحقول FSS','التحقق على مقاييس مكانية متعددة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقارن FSS تكرار الأحداث ضمن نوافذ مكانية، ويقلل حساسية التقييم للإزاحة الصغيرة مقارنة بالمطابقة الخلوية الصارمة. يتغير الحكم باختلاف حجم النافذة والعتبة المختارة."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق مقياس المهارة في الحقول FSS سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم مقياس المهارة في الحقول FSS، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن نتيجة تحقق خلوية صارمة مع FSS عند وجود إزاحة مكانية صغيرة في حقل المطر."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد مقياس المهارة في الحقول FSS على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6710,55,'["شرح أسس مقياس المهارة في الحقول FSS","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('object-based-forecast-verification','التحقق القائم على الأجسام الجوية','الموقع والحجم والشدة والبنية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يحدد التحقق القائم على الأجسام مناطق متصلة في التنبؤ والرصد ثم يقارن خصائصها مثل المركز والمساحة والشدة والشكل. يتأثر بالعتبة وخوارزمية فصل الأجسام، لذلك يجب توثيق الإعدادات."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق التحقق القائم على الأجسام الجوية سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم التحقق القائم على الأجسام الجوية، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مقارنة بين جسم هطول متوقع وآخر مرصود باستخدام المركز والمساحة والشدة."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد التحقق القائم على الأجسام الجوية على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6720,55,'["شرح أسس التحقق القائم على الأجسام الجوية","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('forecast-consistency-across-lead-times','اتساق التنبؤ عبر أزمنة الصلاحية','التغيرات بين الإصدارات المتعاقبة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس الاتساق مدى استقرار السيناريو المتوقع عند الانتقال بين دورات التشغيل وأزمنة الصلاحية. التغير لا يعني بالضرورة خطأ؛ فقد يعكس وصول رصد جديد أو حساسية ديناميكية متزايدة."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق اتساق التنبؤ عبر أزمنة الصلاحية سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم اتساق التنبؤ عبر أزمنة الصلاحية، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح طريقة عرض تبرز تغير توقع الهطول بين أربع دورات تشغيل متعاقبة."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد اتساق التنبؤ عبر أزمنة الصلاحية على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6730,55,'["شرح أسس اتساق التنبؤ عبر أزمنة الصلاحية","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('forecast-benchmarking-and-baselines','المقارنة بخطوط أساس مرجعية','المناخية والاستمرار والنموذج البسيط','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"لا تكتمل قيمة مهارة النموذج دون مقارنته بمرجع بسيط أو مناخي ملائم. تساعد خطوط الأساس على معرفة ما إذا كان التعقيد الإضافي يحقق تحسناً فعلياً عبر المواسم والمناطق."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق المقارنة بخطوط أساس مرجعية سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم المقارنة بخطوط أساس مرجعية، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد خط أساس مناسباً لتوقع درجة الحرارة بعد 24 ساعة وآخر لتوقع حدث نادر."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد المقارنة بخطوط أساس مرجعية على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6740,55,'["شرح أسس المقارنة بخطوط أساس مرجعية","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية'),
('operational-forecast-quality-dashboard','لوحة متابعة جودة التنبؤ التشغيلي','المقاييس والإنذارات والتغيرات الزمنية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تجمع لوحة الجودة مقاييس الانحياز والخطأ والمهارة والاعتمادية حسب المتغير والمنطقة والموسم وزمن الصلاحية. ينبغي إظهار حجم العينة وفترات البيانات وإصدارات النموذج لتجنب المقارنات المضللة."},{"type":"heading","text":"البيانات والمنهجية"},{"type":"text","text":"يتطلب تطبيق لوحة متابعة جودة التنبؤ التشغيلي سجلاً متجانساً للتنبؤات والرصد، مع مطابقة الموقع والارتفاع والوقت والوحدة وتعريف الحدث. يجب فصل بيانات بناء النموذج عن بيانات التقييم المستقل، وتسجيل الإصدارات والتغييرات التشغيلية."},{"type":"heading","text":"خطوات التنفيذ والتحقق"},{"type":"list","items":["تعريف المتغير أو الحدث وعتبة التقييم ومجاله الزمني والمكاني.","إنشاء عينة متطابقة من التنبؤ والرصد ومعالجة القيم المفقودة.","اختيار مقياس يتوافق مع السؤال التشغيلي وليس لمجرد سهولة الحساب.","حساب النتائج حسب الموسم والمنطقة وزمن الصلاحية وحجم العينة.","مقارنة النتائج بخط أساس وشرح حدود الاستنتاج وعدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل أداء التنبؤ","text":"أنشئ عينة تاريخية لتقييم لوحة متابعة جودة التنبؤ التشغيلي، وقسمها زمنياً إلى فترة تطوير وفترة تحقق مستقلة. اعرض المقياس الإجمالي والتوزيع حسب الموسم والمنطقة، ثم تحقق من أن التحسن لا ينتج عن تغير العينة أو تعريف الحدث."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مخطط لوحة جودة شهرية تشمل الحرارة والهطول والرياح والإنذارات الاحتمالية."},{"type":"heading","text":"أخطاء منهجية شائعة"},{"type":"list","items":["تقييم التنبؤ والرصد عند أزمنة أو مواقع غير متطابقة.","استخدام عينة صغيرة للأحداث النادرة دون إظهار عدم اليقين.","اختيار مقياس لا يجيب عن السؤال التشغيلي.","تسرب بيانات الاختبار إلى المعايرة أو التدريب.","إخفاء الانحياز خلف متوسط عام لا يوضح الفروق المحلية."]},{"type":"callout","text":"مبدأ التحقق: اعرض حجم العينة والفترة المرجعية وخط الأساس مع كل مقياس، ولا تفسر رقماً منفرداً دون سياقه."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يساعد لوحة متابعة جودة التنبؤ التشغيلي على تحويل مخرجات النماذج إلى معلومات قابلة للتقييم والقرار، مع إبراز عدم اليقين والتمييز بين جودة التنبؤ وقيمته للمستخدم."}]}'::jsonb,6750,55,'["شرح أسس لوحة متابعة جودة التنبؤ التشغيلي","اختيار البيانات والمقاييس الملائمة","تفسير النتائج وعدم اليقين تشغيلياً"]'::jsonb,'التحقق المتقدم والقيمة التشغيلية')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='التنبؤ التجميعي والاحتمالي' then u1.id else u2.id end,
'التنبؤات الاحتمالية والتحقق المتقدم من النماذج',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;